  if (missingVars.length === 0) {
    res.status(200).json({ 
      status: 'ready', 
      timestamp: new Date().toISOString()
    });
  } else {
    res.status(503).json({ 
      status: 'not ready', 
      message: `Missing required environment variables: ${missingVars.join(', ')}`,
      timestamp: new Date().toISOString()
    });
  }
});

